const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let inputLines = [];
rl.on('line', (line) => {
  inputLines.push(line.trim());
}).on('close', () => {
  if (inputLines.length < 2) return;
  const n = parseInt(inputLines[0], 10);
  const a = inputLines[1];

  // Mapping for each digit to its optimal decomposition into digits 2-9
  // The decomposition maximizes the number of digits and prefers larger digits
  // when sorted descending to form the maximum possible integer.
  const decomp = {
    '0': '',
    '1': '',
    '2': '2',
    '3': '3',
    '4': '322',   // 4! = 3! * 2! * 2!
    '5': '5',
    '6': '53',    // 6! = 5! * 3!
    '7': '7',
    '8': '7222',  // 8! = 7! * 2! * 2! * 2!
    '9': '7332'   // 9! = 7! * 3! * 3! * 2!
  };

  let resultDigits = '';
  for (let i = 0; i < n; i++) {
    resultDigits += decomp[a[i]];
  }

  // Sort digits in descending order to form the maximum number
  const sortedDigits = resultDigits.split('').sort((a, b) => b.localeCompare(a)).join('');
  console.log(sortedDigits);
});
